const _ = require('lodash');

/**
 * Checks if two TypeScript interfaces are compatible.
 *
 * @param {any} interface1 The first interface.
 * @param {any} interface2 The second interface.
 * @returns {boolean} True if the interfaces are compatible, false otherwise.
 */
function areInterfacesCompatible(interface1, interface2) {
  // Helper function for deep comparison
  function deepCompare(obj1, obj2) {
    if (!_.isObject(obj1) && !_.isObject(obj2)) {
      return obj1 === obj2; // Primitive comparison
    }
    if (_.isObject(obj1) && _.isObject(obj2)) {
      // Handle arrays and objects recursively
      if (_.isArray(obj1)) {
        if (_.isArray(obj2)) {
          if (obj1.length !== obj2.length) return false;
          for (let i = 0; i < obj1.length; i++) {
            if (!deepCompare(obj1[i], obj2[i])) return false;
          }
          return true;
        }
        return false;
      }
      return _.isEqual(obj1, obj2); // Use lodash's isEqual
    }
    return false; // If one is an object and the other isn't, they're not equal
  }

  return deepCompare(interface1, interface2);
}


// Example Usage & Testing (Important!)
const InterfaceA = {
  name: 'Alice',
  age: 30,
  address: {
    street: '123 Main St',
    city: 'Anytown'
  }
};

const InterfaceB = {
  name: 'Bob',
  age: 30,
  address: {
    street: '456 Oak Ave',
    city: 'Anytown'
  }
};

const InterfaceC = {
  name: 'Charlie',
  age: 25,
  phone: '555-1212'
};

console.log("Interface A and B compatible?", areInterfacesCompatible(InterfaceA, InterfaceB)); // true
console.log("Interface A and C compatible?", areInterfacesCompatible(InterfaceA, InterfaceC)); // false

// Add more test cases here to cover different scenarios!

