 * @param int $perPage The number of items to display per page.
 * @param int $pageNumber The page number to display (starts at 1).
 *
 * @return array|false  An array containing the current page's data and metadata,
 *                      or false if there are errors or invalid input.
 */
function paginateArray(array $array, int $perPage, int $pageNumber = 1): array|false
{
    // Input validation - crucial for security and preventing errors
    if (empty($array)) {
        return false; // Return false for empty array
    }

    if ($perPage <= 0) {
        return false; // Invalid perPage value
    }

    if ($pageNumber <= 0) {
        return false; // Invalid pageNumber value
    }

    $totalItems = count($array);
    $totalPages = (int)ceil($totalItems / $perPage); // Use ceil to round up

    // Validate pageNumber against totalPages
    if ($pageNumber > $totalPages) {
        return false; // Page number out of range
    }

    // Calculate the start and end indices for the current page
    $start = ($pageNumber - 1) * $perPage;
    $end = $start + $perPage;

    // Extract the current page's data
    $pageData = array_slice($array, $start, $end - $start, true); 

    // Create metadata for the pagination (useful for display)
    $metadata = [
        'totalItems' => $totalItems,
        'totalPages' => $totalPages,
        'currentPage' => $pageNumber,
        'perPage' => $perPage
    ];

    return array_merge($pageData, $metadata);
